 74→/// [`BedrockConverse`] provides an `OpenAI` compatible interface (i.e. `impl Chat` ), for models on AWS bedrock that are compatible with the [Converse API](https://docs.aws.amazon.com/bedrock/latest/APIReference/API_runtime_Converse.html).
 75→pub struct BedrockConverse {
 76→    client: Arc<BedrockClient>,
 77→    model_id: String,
 78→    guardrail: Option<GuardRail>,
 79→}
 80→
 81→impl BedrockConverse {
 82→    #[must_use]
 83→    pub fn new(client: Arc<BedrockClient>, model_id: String) -> Self {
 84→        Self {
 85→            client,
 86→            model_id,
 87→            guardrail: None,
 88→        }
 89→    }
 90→
 91→    #[must_use]
 92→    pub fn with_guardrail(mut self, g: GuardRail) -> Self {
 93→        self.guardrail = Some(g);
 94→        self
 95→    }
 96→
 97→    /// Alter the  [`CreateChatCompletionRequest`] in a way that Bedrock understands.
 98→    /// Instead of performing these changes in the underlying conversion (i.e. within Converse
 99→    /// APIs), we do it here for consistency with other model providers.
100→    fn alter_request(&self, mut req: CreateChatCompletionRequest) -> CreateChatCompletionRequest {
101→        req.model.clone_from(&self.model_id);
102→        // Bedrock should set Option::None parameters to a schema with no inputs, but doesn't.
103→        // Must be done explicitly.
104→        if let Some(ref mut tools) = req.tools {
105→            for t in tools.iter_mut() {
106→                if let ChatCompletionTools::Function(tool) = t
107→                    && tool.function.parameters.is_none()
108→                {
109→                    tool.function.parameters.replace(json!(
110→                        {
111→                            "$schema": "http://json-schema.org/draft-07/schema#",
112→                            "properties": {},
113→                            "required": [],
114→                            "title": "",
115→                            "type": "object"
116→                        }
117→                    ));
118→                }
119→            }
120→        }
121→        req
122→    }
123→
124→    /// Convert [`ChatCompletionRequestMessage`] that are neither [`ChatCompletionRequestMessage::System`] or [`ChatCompletionRequestMessage::Developer`] into the Bedrock equivalent [`Message`] format.
125→    ///
126→    /// Other enum variants will be ignored.
127→    fn convert_non_system_messages(
128→        msgs: Vec<ChatCompletionRequestMessage>,
129→    ) -> Result<Vec<Message>, BuildError> {
130→        msgs.into_iter()
131→            .map(|m| match m {
132→                ChatCompletionRequestMessage::User(ChatCompletionRequestUserMessage {
133→                    content,
134→                    ..
135→                }) => MessageBuilder::default()
136→                    .set_content(Some(vec![ContentBlock::Text(match content {
137→                        ChatCompletionRequestUserMessageContent::Text(s) => s,
138→                        ChatCompletionRequestUserMessageContent::Array(arr) => arr
139→                            .into_iter()
140→                            .filter_map(|p| match p {
141→                                ChatCompletionRequestUserMessageContentPart::Text(
142→                                    ChatCompletionRequestMessageContentPartText { text },
143→                                ) => Some(text),
144→                                _ => None,
145→                            })
146→                            .join(""),
147→                    })]))
148→                    .set_role(Some(ConversationRole::User))
149→                    .build(),
150→                ChatCompletionRequestMessage::Assistant(
151→                    ChatCompletionRequestAssistantMessage {
152→                        content,
153→                        tool_calls,
154→                        ..
155→                    },
156→                ) => {
157→                    let mut message_content = vec![];
158→                    let text_content: Option<String> = match content {
159→                        Some(ChatCompletionRequestAssistantMessageContent::Text(s)) => Some(s),
160→                        Some(ChatCompletionRequestAssistantMessageContent::Array(arr)) => arr
161→                            .into_iter()
162→                            .filter_map(|p| match p {
163→                                ChatCompletionRequestAssistantMessageContentPart::Text(
164→                                    ChatCompletionRequestMessageContentPartText { text },
165→                                ) => Some(text),
166→                                ChatCompletionRequestAssistantMessageContentPart::Refusal(_) => {
167→                                    None
168→                                }
169→                            })
170→                            .join("")
171→                            .into(),
172→                        None => None,
173→                    };
174→
175→                    let mut tool_content = tool_calls.as_ref().map(|tools| {
176→                        tools
177→                            .iter()
178→                            .filter_map(|t| {
179→                                let ChatCompletionMessageToolCalls::Function(
180→                                    ChatCompletionMessageToolCall {
181→                                        id,
182→                                        function: FunctionCall { name, arguments },
183→                                        ..
184→                                    },
185→                                ) = t
186→                                else {
187→                                    return None;
188→                                };
189→
190→                                let tool_input = serde_json::from_str(arguments).ok().map_or(
191→                                    Document::Object(HashMap::default()),
192→                                    value_to_document,
193→                                );
194→                                Some(ContentBlock::ToolUse(
195→                                    ToolUseBlockBuilder::default()
196→                                        .set_tool_use_id(Some(id.clone()))
197→                                        .set_name(Some(name.clone()))
198→                                        .set_input(Some(tool_input))
199→                                        .build()
200→                                        .ok()?,
201→                                ))
202→                            })
203→                            .collect::<Vec<_>>()
204→                    });
205→                    if let Some(messages) = tool_content.as_mut() {
206→                        message_content.append(messages);
207→                    }
208→
209→                    if let Some(text) = text_content {
210→                        message_content.push(ContentBlock::Text(text));
211→                    }
212→
213→                    MessageBuilder::default()
214→                        .set_content(Some(message_content))
215→                        .set_role(Some(ConversationRole::Assistant))
216→                        .build()
217→                }
218→                ChatCompletionRequestMessage::Tool(ChatCompletionRequestToolMessage {
219→                    content,
220→                    tool_call_id,
221→                }) => {
222→                    let block_content = match content {
223→                        ChatCompletionRequestToolMessageContent::Text(t) => {
224→                            vec![ToolResultContentBlock::Text(t)]
225→                        }
226→                        ChatCompletionRequestToolMessageContent::Array(arr) => arr
227→                            .into_iter()
228→                            .map(|s| {
229→                                let ChatCompletionRequestToolMessageContentPart::Text(
230→                                    ChatCompletionRequestMessageContentPartText { text },
231→                                ) = s;
232→                                ToolResultContentBlock::Text(text)
233→                            })
234→                            .collect(),
235→                    };
236→                    MessageBuilder::default()
237→                        .set_content(
238→                            ToolResultBlockBuilder::default()
239→                                .set_content(Some(block_content))
240→                                .set_tool_use_id(Some(tool_call_id))
241→                                .set_status(Some(ToolResultStatus::Success))
242→                                .build()
243→                                .ok()
244→                                .map(|b| vec![ContentBlock::ToolResult(b)]),
245→                        )
246→                        .set_role(Some(ConversationRole::User))
247→                        .build()
248→                }
249→                _ => Err(BuildError::invalid_field(
250→                    "role",
251→                    // Unreachable, but return understandable error.
252→                    "unreachable error: cannot reprocess system prompt as messages",
253→                )),
254→            })
255→            .collect::<Result<Vec<_>, _>>()
256→    }
257→
258→    /// Convert [`ChatCompletionRequestMessage`] that are [`ChatCompletionRequestMessage::System`] or [`ChatCompletionRequestMessage::Developer`] into the Bedrock equivalent [`SystemContentBlock`] format.
259→    ///
260→    /// Other enum variants will be ignored.
261→    fn convert_system_messages(msgs: Vec<ChatCompletionRequestMessage>) -> Vec<SystemContentBlock> {
262→        msgs.into_iter()
263→            .flat_map(|m| match m {
264→                ChatCompletionRequestMessage::System(ChatCompletionRequestSystemMessage {
265→                    content: ChatCompletionRequestSystemMessageContent::Array(arr),
266→                    name: _,
267→                }) => arr
268→                    .into_iter()
269→                    .map(|s| match s {
270→                        ChatCompletionRequestSystemMessageContentPart::Text(
271→                            ChatCompletionRequestMessageContentPartText { text },
272→                        ) => SystemContentBlock::Text(text),
273→                    })
274→                    .collect(),
275→                ChatCompletionRequestMessage::Developer(
276→                    ChatCompletionRequestDeveloperMessage {
277→                        content: ChatCompletionRequestDeveloperMessageContent::Text(s),
278→                        name: _,
279→                    },
280→                )
281→                | ChatCompletionRequestMessage::System(ChatCompletionRequestSystemMessage {
282→                    content: ChatCompletionRequestSystemMessageContent::Text(s),
283→                    name: _,
284→                }) => vec![SystemContentBlock::Text(s)],
285→                ChatCompletionRequestMessage::Developer(
286→                    ChatCompletionRequestDeveloperMessage {
287→                        content: ChatCompletionRequestDeveloperMessageContent::Array(arr),
288→                        name: _,
289→                    },
290→                ) => arr
291→                    .into_iter()
292→                    .map(|s| {
293→                        let ChatCompletionRequestDeveloperMessageContentPart::Text(
294→                            ChatCompletionRequestMessageContentPartText { text },
295→                        ) = s;
296→                        SystemContentBlock::Text(text)
297→                    })
298→                    .collect(),
299→                _ => vec![],
300→            })
301→            .collect()
302→    }
303→
304→    #[expect(clippy::cast_possible_wrap, deprecated)]
305→    fn inference_cfg(req: &CreateChatCompletionRequest) -> InferenceConfiguration {
306→        InferenceConfiguration::builder()
307→            .set_max_tokens(
308→                req.max_completion_tokens
309→                    .or(req.max_tokens)
310→                    .map(|u| u as i32),
311→            )
312→            .set_stop_sequences(req.stop.as_ref().map(|stop| match stop {
313→                StopConfiguration::String(s) => vec![s.clone()],
314→                StopConfiguration::StringArray(arr) => arr.clone(),
315→            }))
316→            .set_temperature(req.temperature)
317→            .set_top_p(req.top_p)
318→            .build()
319→    }
320→
321→    fn to_converse_stream(
322→        &self,
323→        client: &Arc<BedrockClient>,
324→        req: CreateChatCompletionRequest,
325→    ) -> Result<ConverseStreamFluentBuilder, OpenAIError> {
326→        let inf_cfg = Self::inference_cfg(&req);
327→        let CreateChatCompletionRequest {
328→            messages,
329→            metadata,
330→            tool_choice,
331→            tools,
332→            ..
333→        } = req;
334→
335→        // Split system and regular messages. They are separate properties in Bedrock.
336→        let (system, messages): (
337→            Vec<ChatCompletionRequestMessage>,
338→            Vec<ChatCompletionRequestMessage>,
339→        ) = messages.into_iter().partition(|m| {
340→            matches!(
341→                m,
342→                ChatCompletionRequestMessage::System(_)
343→                    | ChatCompletionRequestMessage::Developer(_)
344→            )
345→        });
346→
347→        let system = Self::convert_system_messages(system);
348→        let messages =
349→            Self::convert_non_system_messages(messages).map_err(|e| to_api_error(e.to_string()))?;
350→
351→        let guardrails: Option<GuardrailStreamConfiguration> = self
352→            .guardrail
353→            .as_ref()
354→            .map(std::convert::TryInto::try_into)
355→            .transpose()
356→            .map_err(|e: BuildError| to_api_error(e.to_string()))?;
357→
358→        let mut bldr = client
359→            .client
360→            .converse_stream()
361→            .model_id(self.model_id.clone())
362→            .set_messages(Some(messages))
363→            .inference_config(inf_cfg)
364→            .set_system(Some(system))
365→            .set_guardrail_config(guardrails)
366→            .set_tool_config(tool_config(tools, tool_choice));
367→
368→        if let Some(metadata) = metadata {
369→            // Metadata is a newtype around serde_json::Value - convert and extract object
370→            if let Ok(Value::Object(m)) = serde_json::to_value(&metadata) {
371→                bldr = bldr.set_request_metadata(Some(
372→                    m.into_iter().map(|(k, v)| (k, v.to_string())).collect(),
373→                ));
374→            }
375→        }
376→
377→        Ok(bldr)
378→    }
379→
380→    fn to_converse(
381→        &self,
382→        client: &Arc<BedrockClient>,
383→        req: CreateChatCompletionRequest,
384→    ) -> Result<ConverseFluentBuilder, OpenAIError> {
385→        let inf_cfg = Self::inference_cfg(&req);
386→        let CreateChatCompletionRequest {
387→            messages,
388→            metadata,
389→            tools,
390→            tool_choice,
391→            response_format,
392→            ..
393→        } = req;
394→
395→        tracing::warn!("OpenAI messages={messages:?}");
396→        // Split system and regular messages. They are separate properties in Bedrock.
397→        let (system, messages): (
398→            Vec<ChatCompletionRequestMessage>,
399→            Vec<ChatCompletionRequestMessage>,
400→        ) = messages.into_iter().partition(|m| {
401→            matches!(
402→                m,
403→                ChatCompletionRequestMessage::System(_)
404→                    | ChatCompletionRequestMessage::Developer(_)
405→            )
406→        });
407→
408→        let system = Self::convert_system_messages(system);
409→        let messages =
410→            Self::convert_non_system_messages(messages).map_err(|e| to_api_error(e.to_string()))?;
411→
412→        tracing::warn!("Bedrock messages={messages:?}");
413→        let guardrails: Option<GuardrailConfiguration> = self
414→            .guardrail
415→            .as_ref()
416→            .map(std::convert::TryInto::try_into)
417→            .transpose()
418→            .map_err(|e: BuildError| to_api_error(e.to_string()))?;
419→
420→        let output_config: Option<OutputConfig> = match response_format {
421→            Some(ResponseFormat::JsonObject) => {
422→                return Err(to_api_error(
423→                    "Bedrock does not support 'response_format.type: json_object', only 'json_schema'.",
424→                ));
425→            }
426→            Some(ResponseFormat::JsonSchema {
427→                json_schema:
428→                    ResponseFormatJsonSchema {
429→                        name,
430→                        schema: Some(schema),
431→                        description,
432→                        strict: _,
433→                    },
434→            }) => Some(
435→                OutputConfig::builder()
436→                    .text_format(
437→                        OutputFormat::builder()
438→                            .r#type(OutputFormatType::JsonSchema)
439→                            .structure(OutputFormatStructure::JsonSchema(
440→                                JsonSchemaDefinition::builder()
441→                                    .set_schema(Some(schema.to_string()))
442→                                    .name(name)
443→                                    .set_description(description)
444→                                    .build()
445→                                    .map_err(|e| to_api_error(e.to_string()))?,
446→                            ))
447→                            .build()
448→                            .map_err(|e| to_api_error(e.to_string()))?,
449→                    )
450→                    .build(),
451→            ),
452→            _ => None,
453→        };
454→
455→        let mut bldr = client
456→            .client
457→            .converse()
458→            .model_id(self.model_id.clone())
459→            .set_messages(Some(messages))
460→            .inference_config(inf_cfg)
461→            .set_system(Some(system))
462→            .set_guardrail_config(guardrails)
463→            .set_output_config(output_config)
464→            .set_tool_config(tool_config(tools, tool_choice));
465→
466→        if let Some(metadata) = metadata {
467→            // Metadata is a newtype around serde_json::Value - convert and extract object
468→            if let Ok(Value::Object(m)) = serde_json::to_value(&metadata) {
469→                bldr = bldr.set_request_metadata(Some(
470→                    m.into_iter().map(|(k, v)| (k, v.to_string())).collect(),
471→                ));
472→            }
473→        }
474→
475→        Ok(bldr)
476→    }
477→
478→    #[expect(clippy::cast_possible_truncation, deprecated, clippy::type_complexity)]
479→    fn convert_converse_output(
480→        &self,
481→        output: ConverseOutput,
482→    ) -> Result<CreateChatCompletionResponse, OpenAIError> {
483→        let usage = output.usage().map(convert_usage);
484→
485→        let Some(choices) = output
486→            .output
487→            .map(|o| {
488→                let Message { role, content, .. } =
489→                    o.as_message().map_err(|e| to_api_error(format!("{e:?}")))?;
490→
491→                let data: Vec<(
492→                    (Option<String>, Option<String>),
493→                    Option<ChatCompletionMessageToolCall>,
494→                )> = content
495→                    .iter()
496→                    .map(extract_from_content_block)
497→                    .collect::<Result<Vec<_>, _>>()?;
498→                let (content_and_refusal, tool_calls): (Vec<_>, Vec<_>) = data.into_iter().unzip();
499→                let (content, refusals): (Vec<_>, Vec<_>) = content_and_refusal.into_iter().unzip();
500→
501→                // Convert tool_calls from Vec<ChatCompletionMessageToolCall> to Vec<ChatCompletionMessageToolCalls>
502→                let tool_calls_enum: Vec<ChatCompletionMessageToolCalls> = tool_calls
503→                    .into_iter()
504→                    .flatten()
505→                    .map(ChatCompletionMessageToolCalls::Function)
506→                    .collect();
507→
508→                Ok::<_, OpenAIError>(ChatChoice {
509→                    index: 0,
510→                    message: ChatCompletionResponseMessage {
511→                        content: Some(content.into_iter().flatten().join("\n")),
512→                        refusal: Some(refusals.into_iter().flatten().join("\n")),
513→                        tool_calls: if tool_calls_enum.is_empty() {
514→                            None
515→                        } else {
516→                            Some(tool_calls_enum)
517→                        },
518→                        annotations: None,
519→                        role: try_convert_role(role)?,
520→                        function_call: None,
521→                        audio: None,
522→                    },
523→                    logprobs: None,
524→                    finish_reason: Some(try_convert_finish_reason(&output.stop_reason)?),
525→                })
526→            })
527→            .transpose()?
528→        else {
529→            return Err(to_api_error(
530→                "No outputs received from AWS bedrock converse API",
531→            ));
532→        };
533→
534→        Ok(CreateChatCompletionResponse {
535→            usage,
536→            id: generate_stream_id(&self.model_id),
537→            choices: vec![choices],
538→            created: SystemTime::now()
539→                .duration_since(SystemTime::UNIX_EPOCH)
540→                .map_err(|e| OpenAIError::InvalidArgument(e.to_string()))?
541→                .as_secs() as u32,
542→            model: self.model_id.clone(),
543→            service_tier: None,
544→            system_fingerprint: None,
545→            object: "chat.completion".to_string(),
546→        })
547→    }
548→
549→    fn process_stream(
550→        model: &str,
551→        input_stream: EventReceiver<ConverseStreamOutputPacket, ConverseStreamOutputError>,
552→    ) -> ChatCompletionResponseStream {
553→        // Individual packets in the stream may need information from previous packets to be converted correctly to a  [`CreateChatCompletionStreamResponse`]. This struct track all the necessary information.
554→        #[derive(Default)]
555→        struct StreamState {
556→            id: String,
557→            model: String,
558→            role: Option<Role>,
559→            content_block_index_to_tool_details: HashMap<i32, ToolUseBlockStart>,
560→            content_block_index_to_delta_idx: HashMap<i32, u32>,
561→        }
562→
563→        let state = Arc::new(RwLock::new(StreamState {
564→            id: generate_stream_id(model),
565→            model: model.to_string(),
566→
567→            ..StreamState::default()
568→        }));
569→
570→        Box::pin(into_fallible_stream(input_stream).filter_map(move |packet| {
571→            let state = Arc::clone(&state);
572→
573→            async move {
574→               let mut state_ = state.write().await;
575→               let zz: Option<Result<CreateChatCompletionStreamResponse, OpenAIError>> = match packet {
576→                    Err(SdkError::ServiceError(e)) => {
577→                        match &e.err() {
578→                            &ConverseStreamOutputError::InternalServerException(e) => {
579→                                Some(Err(to_api_error(e.to_string())))
580→                            }
581→                            ee => {
582→                                // TODO specialise
583→                                Some(Err(to_api_error(ee.to_string())))
584→                            }
585→                        }
586→                    }
587→                    Err(e) => {
588→                        Some(Err(to_api_error(e.to_string())))
589→                    }
590→                    Ok(None) => None, // Natural end-of-stream.
591→                    Ok(Some(pkt)) => {
592→                        let value: Option<Result<CreateChatCompletionStreamResponse, OpenAIError>> =
593→                            match pkt {
594→                                ConverseStreamOutputPacket::MessageStart(MessageStartEvent {
595→                                    role,
596→                                    ..
597→                                }) => match try_convert_role(&role) {
598→                                    Ok(r) => {
599→                                        state_.role = Some(r);
600→                                        None
601→                                    }
602→                                    Err(e) => Some(Err(e)),
603→                                },
604→                                ConverseStreamOutputPacket::ContentBlockStart(
605→                                    ContentBlockStartEvent {
606→                                        start: Some(ContentBlockStartInner::ToolUse(tool_use)),
607→                                        content_block_index,
608→                                        ..
609→                                    },
610→                                ) => {
611→                                    state_
612→                                        .content_block_index_to_delta_idx
613→                                        .insert(content_block_index, 0);
614→                                    state_
615→                                        .content_block_index_to_tool_details
616→                                        .insert(content_block_index, tool_use);
617→                                    None
618→                                }
619→                                ConverseStreamOutputPacket::ContentBlockDelta(
620→                                    ContentBlockDeltaEvent {
621→                                        delta: Some(ContentBlockDeltaType::Text(text)),
622→                                        ..
623→                                    },
624→                                ) => Some(create_stream_response(
625→                                    state_.id.as_str(),
626→                                    &state_.model,
627→                                    vec![chat_choice_stream(
628→                                        Some(text),
629→                                        None,
630→                                        state_.role,
631→                                        None,
632→                                        None,
633→                                    )],
634→                                    None,
635→                                )),
636→                                ConverseStreamOutputPacket::ContentBlockDelta(
637→                                    ContentBlockDeltaEvent {
638→                                        delta:
639→                                            Some(ContentBlockDeltaType::ToolUse(ToolUseBlockDelta {
640→                                                input,
641→                                                ..
642→                                            })),
643→                                        content_block_index,
644→                                        ..
645→                                    },
646→                                ) => {
647→                                    let tool_delta_idx = *state_
648→                                        .content_block_index_to_delta_idx
649→                                        .get(&content_block_index)
650→                                        .unwrap_or(&0);
651→
652→                                    if let Some(ToolUseBlockStart {
653→                                        tool_use_id, name, ..
654→                                    }) = state_
655→                                        .content_block_index_to_tool_details
656→                                        .get(&content_block_index)
657→                                    {
658→                                        let z = create_stream_response(
659→                                            state_.id.as_str(),
660→                                            &state_.model,
661→                                            vec![chat_choice_stream(
662→                                                None,
663→                                                Some(vec![ChatCompletionMessageToolCallChunk {
664→                                                    index: tool_delta_idx,
665→                                                    id: Some(tool_use_id.clone()),
666→                                                    r#type: Some(FunctionType::Function),
667→                                                    function: Some(FunctionCallStream {
668→                                                        name: Some(name.clone()),
669→                                                        arguments: Some(input),
670→                                                    }),
671→                                                }]),
672→                                                state_.role,
673→                                                None,
674→                                                None,
675→                                            )],
676→                                            None,
677→                                        );
678→                                        state_
679→                                            .content_block_index_to_delta_idx
680→                                            .insert(content_block_index, tool_delta_idx + 1);
681→                                        Some(z)
682→                                    } else {
683→                                        Some(Err(to_api_error("Invalid stream from Bedrock Converse API. Tool use delta received before starting packet".to_string())))
684→                                    }
685→                                }
686→                                ConverseStreamOutputPacket::MessageStop(MessageStopEvent {
687→                                    stop_reason,
688→                                    ..
689→                                }) => match try_convert_finish_reason(&stop_reason) {
690→                                    Ok(finish_reason) => Some(create_stream_response(
691→                                        state_.id.as_str(),
692→                                        &state_.model,
693→                                        vec![chat_choice_stream(
694→                                            None,
695→                                            None,
696→                                            state_.role,
697→                                            None,
698→                                            Some(finish_reason),
699→                                        )],
700→                                        None,
701→                                    )),
702→                                    Err(e) => Some(Err(e)),
703→                                },
704→                                ConverseStreamOutputPacket::Metadata(
705→                                    ConverseStreamMetadataEvent {
706→                                        usage: Some(usage), ..
707→                                    },
708→                                ) => Some(create_stream_response(
709→                                    state_.id.as_str(),
710→                                    &state_.model,
711→                                    vec![],
712→                                    Some(convert_usage(&usage)),
713→                                )),
714→                                ConverseStreamOutputPacket::ContentBlockStop(_) => None,
715→                                unknown => Some(Err(to_api_error(format!(
716→                                    "Unknown event from Bedrock stream: {unknown:?}"
717→                                )))),
718→                            };
719→                        // Need to drop [`RwLockWriteGuard`] before returning `state.
720→                        value
721→                    }
722→                };
723→               zz
724→            }
725→        }))
726→    }
727→}
728→
729→#[async_trait]
730→impl Chat for BedrockConverse {
731→    async fn chat_stream(
732→        &self,
733→        req: CreateChatCompletionRequest,
734→    ) -> Result<ChatCompletionResponseStream, OpenAIError> {
735→        let input = self.to_converse_stream(&self.client, self.alter_request(req))?;
736→        let output = self
737→            .client
738→            .do_converse_stream(input)
739→            .await
740→            .map_err(|e| to_api_error(e.to_string()))?;
741→        Ok(Self::process_stream(self.model_id.as_str(), output.stream))
742→    }
743→
744→    async fn chat_request(
745→        &self,
746→        req: CreateChatCompletionRequest,
747→    ) -> Result<CreateChatCompletionResponse, OpenAIError> {
748→        let input = self.to_converse(&self.client, self.alter_request(req))?;
749→        let output = self
750→            .client
751→            .do_converse(input)
752→            .await
753→            .map_err(|e| to_api_error(e.to_string()))?;
