        .set_max_tokens(
            req.max_completion_tokens
                .or(req.max_tokens)
                .map(|u| u as i32),
        )
        .set_stop_sequences(req.stop.as_ref().map(|stop| match stop {
            StopConfiguration::String(s) => vec![s.clone()],
            StopConfiguration::StringArray(arr) => arr.clone(),
        }))
        .set_temperature(req.temperature)
        .set_top_p(req.top_p)
        .build()
}

