impl BedrockConverse {
    #[must_use]
    pub fn new(client: Arc<BedrockClient>, model_id: String) -> Self {
        Self {
            client,
            model_id,
            guardrail: None,
        }
    }

    #[must_use]
    pub fn with_guardrail(mut self, g: GuardRail) -> Self {
