        let usage = output.usage().map(convert_usage);

        let Some(choices) = output
            .output
            .map(|o| {
                let Message { role, content, .. } =
                    o.as_message().map_err(|e| to_api_error(format!("{e:?}")))?;

                let data: Vec<(
                    (Option<String>, Option<String>),
                    Option<ChatCompletionMessageToolCall>,
